//! Vanilla 26.1.2 block selection outlines, normalized before positional offsets.
//! Generated by `tools/extract-block-collision-shapes.sh --outline` using the
//! collision table's fingerprinted binary format and parser.

use std::sync::LazyLock;

use crate::collision_shapes::CollisionShapeTable;

const RAW_OUTLINE_SHAPES: &[u8] = include_bytes!("../data/block_outline_shapes_26_1_2.bin");
static VANILLA_OUTLINE_SHAPES: LazyLock<CollisionShapeTable> =
    LazyLock::new(|| CollisionShapeTable::from_binary(RAW_OUTLINE_SHAPES));

#[must_use]
pub fn vanilla_outline_shapes() -> &'static CollisionShapeTable {
    &VANILLA_OUTLINE_SHAPES
}

